 ['overview','home','⌂'],['overview','pinSetup','●'],['accounts','entry','＋'],['farm','farms','▦'],['farm','farmDetail','↗'],['accounts','family','↔'],['accounts','personal','⌂'],['accounts','general','ϟ'],['accounts','milk','◌'],['calendar','alert','☼'],['calendar','calendar','▦'],['settings','panchangSettings','☼'],['settings','guidance','☼'],['manage','shopping','✓'],['manage','assets','▣'],['manage','lend','↗'],['manage','reminders','◷'],['manage','widgets','▥'],['settings','profiles','◎'],['settings','settings','⚙'],['settings','themes','◐'],['settings','security','▣'],['settings','master','⌂'],['settings','generalSettings','⚙'],['settings','farmsSettings','⌂'],['settings','cropsSettings','♧'],['settings','categoriesSettings','▤'],['settings','templates','↗'],['settings','reports','▤'],['settings','backup','↻'],['settings','help','?'],['settings','updates','↑'],['settings','lock','●']
